```python
def balanced_parentheses(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    openings = set(pairs.values())
    for ch in s:
        if ch in pairs:  # closing bracket
            if not stack or stack.pop() != pairs[ch]:
                return False
        elif ch in openings:  # opening bracket
            stack.append(ch)
    return not stack
```

